probe:
package CorsairProbe;
use strict;
use warnings;
use Cwd qw(getcwd);
use File::Temp qw(tempdir);
use lib '/work/lib';
use Module::ScanDeps ();

our $CONTROL_PAYLOAD = 'input.pm';
our $EXPLOIT_PAYLOAD = '>sentinel';
our $LAST_SCAN_ERROR;

sub run_target {
    my ($payload) = @_;
    $LAST_SCAN_ERROR = undef;
    my $root = tempdir('corsair-XXXXXX', TMPDIR => 1, CLEANUP => 1);
    my $old = getcwd();
    chdir $root or die "cannot enter owned directory: $!";
    my ($preserved, $outer_error);
    {
        local $@;
        eval {
            my $original = "owned sentinel bytes\n";
            for my $entry (['sentinel', $original], ['input.pm', "# ordinary owned input\n"], ['>sentinel', "# literal owned input\n"]) {
                open my $out, '>', $entry->[0] or die "cannot create owned fixture: $!";
                print {$out} $entry->[1] or die "cannot write owned fixture: $!";
                close $out or die "cannot close owned fixture: $!";
            }
            my (@found, $scan_error);
            {
                local $@;
                eval { @found = Module::ScanDeps::scan_file($payload); 1 } or $scan_error = "$@";
            }
            $LAST_SCAN_ERROR = $scan_error;
            open my $in, '<', 'sentinel' or die "cannot read owned sentinel: $!";
            my $actual = do { local $/; <$in> };
            close $in or die "cannot close owned sentinel: $!";
            die "unexpected scan result" if !$scan_error && @found;
            die $scan_error if $scan_error && $actual eq $original;
            $preserved = $actual eq $original;
            1;
        } or $outer_error = "$@";
    }
    chdir $old or die "cannot restore owned directory: $!";
    die $outer_error if $outer_error;
    return $preserved ? 1 : 0;
}

1;
